50: impl Default for Player {
51:     fn default() -> Self {
52:         Player { duration: 0.0, position: 0.0, paused: false, speed: 1.0, volume: 100.0, muted: false, looping: LoopMode::Off, eof: false, fps: 25.0, audio_delay: 0.0, chapters: vec![], osd: None }
53:     }
