252: #[derive(Clone, Debug)]
253: pub struct Playlist {
254:     pub items: Vec<String>,
255:     pub cur: Option<usize>,
256:     pub shuffle: bool,
257:     pub repeat: Repeat,
258:     order: Vec<usize>,
259:     seed: u64,
260: }
261: 
262: impl Default for Playlist {
263:     fn default() -> Self {
264:         Playlist { items: vec![], cur: None, shuffle: false, repeat: Repeat::Off, order: vec![], seed: 0x9E3779B97F4A7C15 }
265:     }
266: }
267: 
268: impl Playlist {
269:     pub fn new(items: Vec<String>, start: usize) -> Playlist {
270:         let mut p = Playlist { items, ..Playlist::default() };
271:         p.cur = if p.items.is_empty() { None } else { Some(start.min(p.items.len() - 1)) };
272:         p.rebuild_order();
273:         p
274:     }
275:     fn rng(&mut self) -> u64 {
276:         self.seed ^= self.seed << 13;
277:         self.seed ^= self.seed >> 7;
278:         self.seed ^= self.seed << 17;
279:         self.seed
280:     }
281:     fn rebuild_order(&mut self) {
282:         let mut o: Vec<usize> = (0..self.items.len()).collect();
283:         if self.shuffle {
284:             for i in (1..o.len()).rev() {
285:                 let j = (self.rng() % (i as u64 + 1)) as usize;
286:                 o.swap(i, j);
287:             }
288:             // current item first so toggling shuffle never changes what is playing
289:             if let Some(c) = self.cur {
290:                 if let Some(p) = o.iter().position(|x| *x == c) {
291:                     o.swap(0, p);
292:                 }
293:             }
294:         }
295:         self.order = o;
296:     }
297:     pub fn set_shuffle(&mut self, on: bool) {
298:         self.shuffle = on;
299:         self.rebuild_order();
300:     }
301:     pub fn add(&mut self, path: String) {
302:         self.items.push(path);
303:         if self.cur.is_none() {
304:             self.cur = Some(0);
305:         }
306:         self.rebuild_order();
307:     }
308:     pub fn remove(&mut self, i: usize) {
309:         if i >= self.items.len() {
310:             return;
311:         }
312:         self.items.remove(i);
313:         self.cur = match self.cur {
314:             _ if self.items.is_empty() => None,
315:             Some(c) if c > i => Some(c - 1),
316:             Some(c) => Some(c.min(self.items.len() - 1)),
317:             None => None,
318:         };
319:         self.rebuild_order();
320:     }
321:     pub fn current(&self) -> Option<&str> {
322:         self.cur.and_then(|c| self.items.get(c)).map(|s| s.as_str())
323:     }
324:     fn pos_in_order(&self) -> Option<usize> {
325:         let c = self.cur?;
326:         self.order.iter().position(|x| *x == c)
327:     }
328:     /// Index to play after the current one finished (`auto`) or when the user presses Next.
329:     pub fn next(&mut self, auto: bool) -> Option<usize> {
330:         if self.items.is_empty() {
331:             return None;
332:         }
333:         if auto && self.repeat == Repeat::One {
334:             return self.cur;
335:         }
336:         let p = self.pos_in_order()?;
337:         let n = if p + 1 < self.order.len() {
338:             self.order[p + 1]
339:         } else if self.repeat == Repeat::All || !auto {
340:             if self.shuffle {
341:                 self.rebuild_order();
342:             }
343:             self.order[0]
344:         } else {
345:             return None;
346:         };
347:         self.cur = Some(n);
348:         self.cur
349:     }
350:     pub fn prev(&mut self) -> Option<usize> {
351:         let p = self.pos_in_order()?;
352:         let n = if p > 0 { self.order[p - 1] } else { *self.order.last()? };
353:         self.cur = Some(n);
354:         self.cur
355:     }
356:     pub fn cycle_repeat(&mut self) {
357:         self.repeat = match self.repeat {
358:             Repeat::Off => Repeat::All,
359:             Repeat::All => Repeat::One,
360:             Repeat::One => Repeat::Off,
361:         };
362:     }
363: }
