68: fn parse_rate(s: &str) -> f64 {
69:     match s.split_once('/') {
70:         Some((n, d)) => {
71:             let (n, d): (f64, f64) = (n.parse().unwrap_or(0.0), d.parse().unwrap_or(0.0));
72:             if d > 0.0 {
73:                 n / d
74:             } else {
75:                 0.0
76:             }
77:         }
78:         None => s.parse().unwrap_or(0.0),
79:     }
80: }
