82: fn s(v: &Value, k: &str) -> String {
83:     v.get(k).and_then(|x| x.as_str()).unwrap_or("").to_string()
84: }
85: fn num(v: &Value, k: &str) -> f64 {
86:     match v.get(k) {
87:         Some(Value::String(t)) => t.parse().unwrap_or(0.0),
88:         Some(Value::Number(n)) => n.as_f64().unwrap_or(0.0),
89:         _ => 0.0,
90:     }
91: }
