221: /// SMPTE-style bars, a bouncing ball and a burnt-in timecode. Deterministic: same `t` → same pixels.
222: pub fn render_testcard(w: usize, h: usize, t: f64, fps: f64) -> Frame {
223:     let (w, h) = (w.max(16), h.max(16));
224:     let mut rgba = vec![0u8; w * h * 4];
225:     const BARS: [[u8; 3]; 7] = [[235, 235, 235], [235, 235, 16], [16, 235, 235], [16, 235, 16], [235, 16, 235], [235, 16, 16], [16, 16, 235]];
226:     let bars_h = h * 2 / 3;
227:     for y in 0..h {
228:         for x in 0..w {
229:             let c = if y < bars_h {
230:                 BARS[(x * 7 / w).min(6)]
231:             } else if y < bars_h + h / 12 {
232:                 let g = (x * 255 / w) as u8;
233:                 [g, g, g]
234:             } else {
235:                 [18, 22, 34]
236:             };
237:             put(&mut rgba, w, x, y, c);
238:         }
239:     }
240:     // dim the bars a little so overlaid UI stays legible
241:     for px in rgba[..bars_h * w * 4].chunks_exact_mut(4) {
242:         for c in &mut px[..3] {
243:             *c = (*c as u16 * 7 / 10) as u8;
244:         }
245:     }
246:     // ball
247:     let phase = (t / 6.0 * std::f64::consts::TAU).sin();
248:     let bx = (w as f64 * (0.5 + 0.42 * phase)) as i64;
249:     let by = (bars_h as f64 + (h - bars_h) as f64 * 0.62) as i64;
250:     let r = (h / 16).max(3) as i64;
251:     for y in (by - r).max(0)..(by + r).min(h as i64) {
252:         for x in (bx - r).max(0)..(bx + r).min(w as i64) {
253:             if (x - bx).pow(2) + (y - by).pow(2) <= r * r {
254:                 put(&mut rgba, w, x as usize, y as usize, [255, 214, 96]);
255:             }
256:         }
257:     }
258:     let tt = t.max(0.0);
259:     let frame_no = (tt * fps.max(1.0)) as u64;
260:     let tc = format!("{:02}:{:02}:{:02}", (tt as u64) / 3600, ((tt as u64) / 60) % 60, (tt as u64) % 60);
261:     let scale = (w / 90).max(1);
262:     draw_text(&mut rgba, w, h, w / 16, h * 2 / 3 + h / 12 + scale * 2, scale, &tc, [236, 240, 250]);
263:     draw_text(&mut rgba, w, h, w / 16, h - 9 * scale - 4, scale.max(2) / 2 + 1, &format!("{frame_no:06}"), [140, 156, 190]);
264:     Frame { w, h, rgba, pts: frame_no as f64 / fps.max(1.0) }
265: }
