284: impl FrameSource for TestCard {
285:     fn info(&self) -> &MediaInfo {
286:         &self.info
287:     }
288:     fn seek(&mut self, _t: f64) {
289:         self.last = None;
290:     }
291:     fn poll(&mut self, clock: f64) -> Option<Frame> {
292:         let idx = (clock.max(0.0) * self.fps) as u64;
293:         if self.last == Some(idx) {
294:             return None;
295:         }
296:         self.last = Some(idx);
297:         Some(render_testcard(self.w, self.h, idx as f64 / self.fps, self.fps))
298:     }
299:     fn name(&self) -> &'static str {
300:         "test card"
301:     }
302: }
