204: impl SubTrack {
205:     pub fn new(name: impl Into<String>, lang: impl Into<String>, cues: Vec<Cue>) -> Self {
206:         let max_dur = cues.iter().map(|c| c.end - c.start).fold(0.0, f64::max);
207:         SubTrack { name: name.into(), lang: lang.into(), cues, max_dur, delay: 0.0 }
208:     }
209:     pub fn from_bytes(name: &str, bytes: &[u8]) -> SubTrack {
210:         let lang = guess_lang(name);
211:         SubTrack::new(name, lang, parse(&decode_bytes(bytes)))
212:     }
213:     pub fn len(&self) -> usize {
214:         self.cues.len()
215:     }
216:     pub fn is_empty(&self) -> bool {
217:         self.cues.is_empty()
218:     }
219:     pub fn cues(&self) -> &[Cue] {
220:         &self.cues
221:     }
222: 
223:     /// Cues visible at media time `t` (the delay is applied here).
224:     pub fn active(&self, t: f64) -> Vec<&Cue> {
225:         let t = t - self.delay;
226:         let idx = self.cues.partition_point(|c| c.start <= t);
227:         let mut out = vec![];
228:         for c in self.cues[..idx].iter().rev() {
229:             if c.start + self.max_dur < t {
230:                 break;
231:             }
232:             if c.end > t {
233:                 out.push(c);
234:             }
235:         }
236:         out.reverse();
237:         out
238:     }
239: 
240:     /// Start of the next cue after `t` (for "jump to next subtitle").
241:     pub fn next_start(&self, t: f64) -> Option<f64> {
242:         let t = t - self.delay;
243:         let i = self.cues.partition_point(|c| c.start <= t + 1e-3);
244:         self.cues.get(i).map(|c| c.start + self.delay)
245:     }
246:     pub fn prev_start(&self, t: f64) -> Option<f64> {
247:         let t = t - self.delay;
248:         let i = self.cues.partition_point(|c| c.start < t - 1e-3);
249:         i.checked_sub(1).and_then(|i| self.cues.get(i)).map(|c| c.start + self.delay)
250:     }
251: }
