171: impl SmartApp {
172:     // ───────────── opening ─────────────
173:     pub fn eiga_cmd(&mut self, c: &str) {
174:         let (name, arg) = c.split_once(':').unwrap_or((c, ""));
175:         match name {
176:             "open" => {
177:                 if let Some((fs, path)) = arg.split_once('|') {
178:                     self.eiga_open(Location::new(fs, path));
179:                 }
180:             }
181:             "play_idx" => {
182:                 if let Ok(i) = arg.parse::<usize>() {
183:                     self.eiga_play_index(i);
184:                 }
185:             }
186:             "sub" => {
187:                 let e = &mut self.shell.eiga;
188:                 e.sub_i = if arg == "off" { None } else { arg.parse().ok().filter(|i| *i < e.subs.len()) };
189:                 let msg = match e.sub_i.and_then(|i| e.subs.get(i)) {
190:                     Some(t) => format!("Subtitles: {}", t.name),
191:                     None => "Subtitles off".to_string(),
192:                 };
193:                 e.osd = Some((msg, self.time));
194:             }
195:             "audio" => {
196:                 if let Ok(i) = arg.parse::<usize>() {
197:                     self.shell.eiga.audio_i = i;
198:                     self.eiga_restart_audio();
199:                     self.shell.eiga.osd = Some((format!("Audio track {}", i + 1), self.time));
200:                 }
201:             }
202:             "speed" => {
203:                 if let Ok(s) = arg.parse::<f64>() {
204:                     let ev = self.shell.eiga.player.set_speed(s);
205:                     self.eiga_events(ev);
206:                 }
207:             }
208:             "cmd" => {
209:                 let b = default_bindings();
210:                 if let Some(x) = b.iter().find(|x| x.help == arg) {
211:                     self.eiga_run(x.cmd);
212:                 }
213:             }
214:             "aspect" => {
215:                 self.shell.eiga.aspect = arg.parse().unwrap_or(0);
216:             }
217:             "list" => self.shell.eiga.show_list = !self.shell.eiga.show_list,
218:             "settings" => self.shell.settings = Some((crate::shell::AppId::Video, 0)),
219:             "remove" => {
220:                 if let Ok(i) = arg.parse::<usize>() {
221:                     let (was_cur, next) = {
222:                         let e = &mut self.shell.eiga;
223:                         let was_cur = e.playlist.cur == Some(i);
224:                         e.playlist.remove(i);
225:                         e.locs.remove(i.min(e.locs.len().saturating_sub(1)));
226:                         let next = if was_cur { e.playlist.cur } else { None };
227:                         if !was_cur {
228:                             if let Some(c) = e.playlist.cur {
229:                                 e.playlist.cur = Some(c.min(e.locs.len().saturating_sub(1)));
230:                             }
231:                         }
232:                         (was_cur, next)
233:                     };
234:                     if was_cur {
235:                         match next {
236:                             Some(n) => self.eiga_play_index(n),
237:                             None => {
238:                                 self.eiga_cleanup();
239:                                 self.shell.eiga.title.clear();
240:                             }
241:                         }
242:                     }
243:                 }
244:             }
245:             "reveal" => {
246:                 if let Ok(i) = arg.parse::<usize>() {
247:                     if let Some(l) = self.shell.eiga.locs.get(i).cloned() {
248:                         if let Some(par) = l.parent() {
249:                             self.push_act(Act::OpenApp(crate::shell::AppId::Files));
250:                             self.push_act(Act::Nav(Route::Loc(par)));
251:                         }
252:                     }
253:                 }
254:             }
255:             "copypath" => {
256:                 if let Ok(i) = arg.parse::<usize>() {
257:                     if let Some(l) = self.shell.eiga.locs.get(i).cloned() {
258:                         self.acts.push(Act::CopyText(l.path.clone()));
259:                     }
260:                 }
261:             }
262:             _ => {}
263:         }
264:     }
