266:     fn eiga_siblings(&self, l: &Location) -> Vec<Location> {
267:         let Some(parent) = l.parent() else { return vec![l.clone()] };
268:         let Some(v) = self.be.registry.get(&parent.fs) else { return vec![l.clone()] };
269:         let mut out: Vec<Location> = v.list(&parent.path).unwrap_or_default().into_iter().filter(|e| !e.is_dir && (e.kind == Kind::Video || VIDEO_EXTS.contains(&e.ext.to_ascii_lowercase().as_str()))).map(|e| e.loc).collect();
270:         out.sort_by_key(|x| x.name().to_lowercase());
271:         if out.is_empty() {
272:             out.push(l.clone());
273:         }
274:         out
275:     }
