277:     pub fn eiga_open(&mut self, l: Location) {
278:         self.open_app(crate::shell::AppId::Video);
279:         let locs = self.eiga_siblings(&l);
280:         let start = locs.iter().position(|x| *x == l).unwrap_or(0);
281:         self.shell.eiga.playlist = Playlist::new(locs.iter().map(|x| x.name()).collect(), start);
282:         self.shell.eiga.locs = locs;
283:         self.eiga_load(l);
284:     }
