286:     fn eiga_play_index(&mut self, i: usize) {
287:         if let Some(l) = self.shell.eiga.locs.get(i).cloned() {
288:             self.shell.eiga.playlist.cur = Some(i);
289:             self.eiga_load(l);
290:         }
291:     }
