411:     fn eiga_events(&mut self, evs: Vec<PEvent>) {
412:         for ev in evs {
413:             match ev {
414:                 PEvent::Seek(t) => {
415:                     if let Some(s) = self.shell.eiga.src.as_mut() {
416:                         s.seek(t);
417:                     }
418:                     self.eiga_restart_audio();
419:                 }
420:                 PEvent::PauseChanged(p) => {
421:                     #[cfg(not(target_arch = "wasm32"))]
422:                     if let Some(a) = self.shell.eiga.audio.as_mut() {
423:                         if p {
424:                             a.player.pause()
425:                         } else {
426:                             a.player.play()
427:                         }
428:                     }
429:                     self.shell.eiga.osd = Some((if p { "Paused" } else { "Playing" }.to_string(), self.time));
430:                 }
431:                 PEvent::SpeedChanged(_) => self.eiga_restart_audio(),
432:                 PEvent::VolumeChanged => {
433:                     #[cfg(not(target_arch = "wasm32"))]
434:                     {
435:                         let g = self.shell.eiga.player.gain();
436:                         if let Some(a) = self.shell.eiga.audio.as_mut() {
437:                             a.player.set_volume(g);
438:                         }
439:                     }
440:                 }
441:                 PEvent::Ended => {
442:                     let next = self.shell.eiga.playlist.next(true);
443:                     if let Some(i) = next {
444:                         self.eiga_play_index(i);
445:                     }
446:                 }
447:                 PEvent::Osd => {}
448:             }
449:         }
450:         let t = self.time;
451:         if let Some(m) = self.shell.eiga.player.osd.take() {
452:             self.shell.eiga.osd = Some((m, t));
453:         }
454:     }
455: 
456:     fn eiga_run(&mut self, cmd: Cmd) {
457:         let (evs, rest) = self.shell.eiga.player.apply(cmd);
458:         self.eiga_events(evs);
459:         let Some(cmd) = rest else { return };
460:         let t = self.time;
461:         match cmd {
462:             Cmd::ToggleFullscreen => {
463:                 let e = &mut self.shell.eiga;
464:                 e.theater = !e.theater;
465:                 e.fs_dirty = true;
466:             }
467:             Cmd::Close => {
468:                 if self.shell.eiga.theater {
469:                     self.eiga_run(Cmd::ToggleFullscreen);
470:                 } else {
471:                     self.shell.video_w.open = false;
472:                 }
473:             }
474:             Cmd::ToggleStats => self.shell.eiga.show_stats = !self.shell.eiga.show_stats,
475:             Cmd::ToggleHelp => self.shell.eiga.show_help = !self.shell.eiga.show_help,
476:             Cmd::TogglePlaylist => self.shell.eiga.show_list = !self.shell.eiga.show_list,
477:             Cmd::ToggleHud => self.shell.eiga.last_move = if self.shell.eiga.last_move > t + 1000.0 { t } else { t + 100000.0 },
478:             Cmd::JumpTo => self.shell.eiga.jump = Some(String::new()),
479:             Cmd::CycleAspect => {
480:                 let e = &mut self.shell.eiga;
481:                 e.aspect = (e.aspect + 1) % 4;
482:                 e.osd = Some((format!("Aspect: {}", ["fit", "fill", "16:9", "4:3"][e.aspect as usize]), t));
483:             }
484:             Cmd::Zoom(d) => {
485:                 let e = &mut self.shell.eiga;
486:                 e.zoom = (e.zoom + d).clamp(0.5, 3.0);
487:                 e.osd = Some((format!("Zoom {:.0}%", e.zoom * 100.0), t));
488:             }
489:             Cmd::Rotate => {
490:                 let e = &mut self.shell.eiga;
491:                 e.rotate = (e.rotate + 1) % 4;
492:                 e.osd = Some((format!("Rotated {}\u{b0}", e.rotate as u32 * 90), t));
493:             }
494:             Cmd::CycleSub => {
495:                 let e = &mut self.shell.eiga;
496:                 e.sub_i = match e.sub_i {
497:                     None if !e.subs.is_empty() => Some(0),
498:                     Some(i) if i + 1 < e.subs.len() => Some(i + 1),
499:                     _ => None,
500:                 };
501:                 let m = match e.sub_i.and_then(|i| e.subs.get(i)) {
502:                     Some(s) => format!("Subtitles: {}", s.name),
503:                     None => if e.subs.is_empty() { "No subtitles found for this video".to_string() } else { "Subtitles off".to_string() },
504:                 };
505:                 e.osd = Some((m, t));
506:             }
507:             Cmd::CycleAudio => {
508:                 let n = self.shell.eiga.info.as_ref().map(|i| i.audio.len()).unwrap_or(0);
509:                 if n > 1 {
510:                     self.shell.eiga.audio_i = (self.shell.eiga.audio_i + 1) % n;
511:                     self.eiga_restart_audio();
512:                     self.shell.eiga.osd = Some((format!("Audio track {} of {n}", self.shell.eiga.audio_i + 1), t));
513:                 } else {
514:                     self.shell.eiga.osd = Some(("Only one audio track".into(), t));
515:                 }
516:             }
517:             Cmd::SubDelay(d) => {
518:                 let e = &mut self.shell.eiga;
519:                 if let Some(tr) = e.sub_i.and_then(|i| e.subs.get_mut(i)) {
520:                     let m = eiga_core::player::nudge_sub_delay(tr, d);
521:                     e.osd = Some((m, t));
522:                 }
523:             }
524:             Cmd::SubScale(d) => {
525:                 let e = &mut self.shell.eiga;
526:                 e.sub_scale = (e.sub_scale + d).clamp(0.5, 2.5);
527:                 e.osd = Some((format!("Subtitle size {:.0}%", e.sub_scale * 100.0), t));
528:             }
529:             Cmd::NextSubCue | Cmd::PrevSubCue => {
530:                 let (pos, next) = (self.shell.eiga.player.position, cmd == Cmd::NextSubCue);
531:                 let target = {
532:                     let e = &self.shell.eiga;
533:                     e.sub_i.and_then(|i| e.subs.get(i)).and_then(|s| if next { s.next_start(pos) } else { s.prev_start(pos) })
534:                 };
535:                 if let Some(t) = target {
536:                     let ev = self.shell.eiga.player.seek_abs(t);
537:                     self.eiga_events(ev);
538:                 }
539:             }
540:             Cmd::NextItem | Cmd::PrevItem => {
541:                 let i = if cmd == Cmd::NextItem { self.shell.eiga.playlist.next(false) } else { self.shell.eiga.playlist.prev() };
542:                 if let Some(i) = i {
543:                     self.eiga_play_index(i);
544:                 }
545:             }
546:             Cmd::ToggleShuffle => {
547:                 let pl = &mut self.shell.eiga.playlist;
548:                 let on = !pl.shuffle;
549:                 pl.set_shuffle(on);
550:                 self.shell.eiga.osd = Some((format!("Shuffle {}", if on { "on" } else { "off" }), t));
551:             }
552:             Cmd::CycleRepeat => {
553:                 self.shell.eiga.playlist.cycle_repeat();
554:                 let r = self.shell.eiga.playlist.repeat;
555:                 self.shell.eiga.osd = Some((format!("Repeat: {}", match r { Repeat::Off => "off", Repeat::All => "all", Repeat::One => "one" }), t));
556:             }
557:             Cmd::OpenFile => self.eiga_pick(),
558:             Cmd::Screenshot => self.eiga_screenshot(),
559:             _ => {}
560:         }
561:     }
