563:     fn eiga_drop(&mut self, files: Vec<egui::DroppedFileHandle>) {
564:         let t = self.time;
565:         let mut videos: Vec<Location> = vec![];
566:         let mut subs_added = 0usize;
567:         for f in &files {
568:             let ext = f.path().extension().and_then(|e| e.to_str()).unwrap_or("").to_ascii_lowercase();
569:             let is_video = ["mp4", "mkv", "mov", "webm", "avi", "m4v", "ts"].contains(&ext.as_str());
570:             let is_sub = matches!(ext.as_str(), "srt" | "vtt" | "ass" | "ssa");
571:             #[cfg(not(target_arch = "wasm32"))]
572:             if is_video {
573:                 videos.push(Location::new("file", f.path().to_string_lossy().to_string()));
574:             }
575:             #[cfg(not(target_arch = "wasm32"))]
576:             if is_sub {
577:                 if let Ok(b) = f.bytes() {
578:                     let tr = SubTrack::from_bytes(&f.path().file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(), &b);
579:                     if !tr.is_empty() {
580:                         self.shell.eiga.sub_i = Some(self.shell.eiga.subs.len());
581:                         self.shell.eiga.subs.push(tr);
582:                         subs_added += 1;
583:                     }
584:                 }
585:             }
586:         }
587:         #[cfg(target_arch = "wasm32")]
588:         {
589:             if !files.is_empty() {
590:                 self.shell.eiga.osd = Some(("File drops open real videos in the desktop app".into(), t));
591:                 return;
592:             }
593:         }
594:         if !videos.is_empty() {
595:             let l = videos[0].clone();
596:             let nm = l.name();
597:             self.eiga_open(l);
598:             self.shell.eiga.osd = Some((format!("Opened {nm}"), t));
599:         } else if subs_added > 0 {
600:             self.shell.eiga.osd = Some((format!("{} subtitle track(s) added", subs_added), t));
601:         }
602:     }
