604:     fn eiga_pick(&mut self) {
605:         #[cfg(not(target_arch = "wasm32"))]
606:         {
607:             use std::sync::mpsc::channel;
608:             if self.shell.eiga.picker_rx.is_some() {
609:                 return;
610:             }
611:             let (tx, rx) = channel();
612:             self.shell.eiga.picker_rx = Some(rx);
613:             // the blocking dialog runs on its own thread so the frame loop never stalls
614:             std::thread::spawn(move || {
615:                 let files = rfd::FileDialog::new().add_filter("Video", &["mp4", "mkv", "mov", "webm", "avi", "m4v", "ts"]).add_filter("Subtitles", &["srt", "vtt", "ass", "ssa"]).pick_files();
616:                 let _ = tx.send(files.unwrap_or_default());
617:             });
618:         }
619:         #[cfg(target_arch = "wasm32")]
620:         {
621:             self.shell.eiga.osd = Some(("Drop a video onto the player instead".into(), self.time));
622:         }
623:     }
624: 
625:     fn eiga_poll_picker(&mut self) {
626:         #[cfg(not(target_arch = "wasm32"))]
627:         if let Some(rx) = self.shell.eiga.picker_rx.as_ref() {
628:             if let Ok(paths) = rx.try_recv() {
629:                 self.shell.eiga.picker_rx = None;
630:                 if paths.is_empty() {
631:                     return;
632:                 }
633:                 let first_video = paths.iter().position(|p| {
634:                     p.extension().and_then(|e| e.to_str()).map(|e| e.to_ascii_lowercase()).map(|e| ["mp4", "mkv", "mov", "webm", "avi", "m4v", "ts"].contains(&e.as_str())).unwrap_or(false)
635:                 });
636:                 if let Some(i) = first_video {
637:                     let l = Location::new("file", paths[i].to_string_lossy().to_string());
638:                     self.eiga_open(l);
639:                     // extra subtitle files chosen alongside the video
640:                     for p in paths.iter().filter(|p| {
641:                         p.extension().and_then(|e| e.to_str()).map(|e| matches!(e.to_ascii_lowercase().as_str(), "srt" | "vtt" | "ass" | "ssa")).unwrap_or(false)
642:                     }) {
643:                         if let Ok(b) = std::fs::read(p) {
644:                             let t = SubTrack::from_bytes(p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default().as_str(), &b);
645:                             if !t.is_empty() {
646:                                 self.shell.eiga.sub_i = Some(self.shell.eiga.subs.len());
647:                                 self.shell.eiga.subs.push(t);
648:                             }
649:                         }
650:                     }
651:                 } else {
652:                     let np = paths.len();
653:                     // only subtitle files were chosen: attach them to the current video
654:                     for p in paths {
655:                         if let Ok(b) = std::fs::read(&p) {
656:                             let t = SubTrack::from_bytes(p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default().as_str(), &b);
657:                             if !t.is_empty() {
658:                                 self.shell.eiga.sub_i = Some(self.shell.eiga.subs.len());
659:                                 self.shell.eiga.subs.push(t);
660:                             }
661:                         }
662:                     }
663:                     self.shell.eiga.osd = Some((format!("{np} subtitle track(s) added"), self.time));
664:                 }
665:             }
666:         }
667:     }
