669:     fn eiga_screenshot(&mut self) {
670:         #[cfg(not(target_arch = "wasm32"))]
671:         {
672:             let t = self.time;
673:             let e = &self.shell.eiga;
674:             let msg = match (&e.src, std::env::var("HOME")) {
675:                 (Some(_), Ok(home)) if e.frames_shown > 0 => {
676:                     let dir = std::path::PathBuf::from(home).join("Pictures");
677:                     let _ = std::fs::create_dir_all(&dir);
678:                     let f = dir.join(format!("Eiga {} {}.png", e.title.replace('/', "-"), fmt_time(e.player.position).replace(':', "-")));
679:                     match e.last_rgba.as_ref() {
680:                         Some((w, h, px)) => match image::save_buffer(&f, px, *w as u32, *h as u32, image::ColorType::Rgba8) {
681:                             Ok(()) => format!("Saved {}", f.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default()),
682:                             Err(er) => format!("Screenshot failed: {er}"),
683:                         },
684:                         None => "Nothing to capture yet".to_string(),
685:                     }
686:                 }
687:                 _ => "Nothing to capture yet".to_string(),
688:             };
689:             self.shell.eiga.osd = Some((msg, t));
690:         }
691:         #[cfg(target_arch = "wasm32")]
692:         {
693:             let t = self.time;
694:             self.shell.eiga.osd = Some(("Screenshots are saved by the desktop app".into(), t));
695:         }
