698:     fn eiga_keys(&mut self, ctx: &egui::Context) {
699:         if self.shell.eiga.jump.is_some() || ctx.egui_wants_keyboard_input() {
700:             return;
701:         }
702:         let evs: Vec<egui::Event> = ctx.input(|i| i.events.clone());
703:         for ev in evs {
704:             if let egui::Event::Key { key, pressed: true, modifiers, .. } = ev {
705:                 if modifiers.command && !modifiers.ctrl {
706:                     continue;
707:                 }
708:                 let Some(n) = key_name(key, modifiers.shift) else { continue };
709:                 let cmd = lookup(&self.shell.eiga.bindings, n, modifiers.ctrl || modifiers.command, modifiers.shift, modifiers.alt);
710:                 if let Some(c) = cmd {
711:                     self.shell.eiga.last_move = self.time;
712:                     self.eiga_run(c);
713:                 }
714:             }
715:         }
716:     }
