772:     pub fn eiga_settings(&mut self, ui: &mut Ui, win: Rect) {
773:         use crate::appkit::SRow;
774:         let pages = [("play", "Playback"), ("subtitles", "Subtitles"), ("tuning-2", "Video & audio"), ("keyboard", "Behaviour")];
775:         let rows_for = |app: &SmartApp, page: usize| -> Vec<SRow> {
776:             let e = &app.shell.eiga;
777:             match page {
778:                 0 => vec![
779:                     SRow::Slider { icon: "bolt", label: "Default speed", sub: "Every new video starts at this speed", v: e.cfg_def_speed as f32, lo: 0.25, hi: 4.0, unit: "\u{d7}" },
780:                     SRow::Toggle { icon: "repeat-one", label: "Repeat file by default", sub: "Loop each file until you skip", on: e.cfg_loop_default },
781:                     SRow::Toggle { icon: "widget", label: "Double-click for fullscreen", sub: "Otherwise double-click does nothing", on: e.cfg_double_click },
782:                 ],
783:                 1 => vec![
784:                     SRow::Slider { icon: "text", label: "Subtitle size", sub: "Relative to the video height", v: e.cfg_sub_size * 100.0, lo: 50.0, hi: 250.0, unit: "%" },
785:                     SRow::Button { icon: "sort-vertical", label: "Reset subtitle size", sub: "Back to 100%", cta: "Reset" },
786:                 ],
787:                 2 => vec![
788:                     SRow::Slider { icon: "volume-loud", label: "Volume", sub: "Above 100% the audio is amplified", v: e.player.volume, lo: 0.0, hi: eiga_core::player::MAX_VOLUME, unit: "%" },
789:                     SRow::Toggle { icon: "volume-cross", label: "Mute", sub: "Silence without touching the volume", on: e.player.muted },
790:                     SRow::Choice { icon: "full-screen", label: "Aspect ratio", sub: "How the picture fits the window", opts: &["Fit", "Fill", "16:9", "4:3"], sel: e.aspect as usize },
791:                 ],
792:                 _ => vec![
793:                     SRow::Slider { icon: "clock-circle", label: "Hide controls after", sub: "Seconds of idle time before the HUD fades", v: e.cfg_hide_secs, lo: 1.0, hi: 8.0, unit: " s" },
794:                     SRow::Button { icon: "restart", label: "Reset all Eiga settings", sub: "Speed, subtitles and behaviour", cta: "Reset" },
795:                 ],
796:             }
797:         };
798:         if let Some((page, row, val)) = self.draw_app_settings(ui, win, crate::shell::AppId::Video, &pages, &rows_for) {
799:             let e = &mut self.shell.eiga;
800:             match (page, row, val) {
801:                 (0, 0, crate::appkit::SVal::F(v)) => e.cfg_def_speed = (v as f64).clamp(0.25, 4.0),
802:                 (0, 1, crate::appkit::SVal::Bool(b)) => e.cfg_loop_default = b,
803:                 (0, 2, crate::appkit::SVal::Bool(b)) => e.cfg_double_click = b,
804:                 (1, 0, crate::appkit::SVal::F(v)) => e.cfg_sub_size = (v / 100.0).clamp(0.5, 2.5),
805:                 (1, 1, _) => {
806:                     e.cfg_sub_size = 1.0;
807:                     self.toast("Subtitle size reset", true);
808:                 }
809:                 (2, 0, crate::appkit::SVal::F(v)) => {
810:                     let d = v - e.player.volume;
811:                     let evs = if d.abs() > 0.5 { e.player.volume_step(d) } else { vec![] };
812:                     drop(e);
813:                     self.eiga_events(evs);
814:                 }
815:                 (2, 1, crate::appkit::SVal::Bool(b)) => {
816:                     let evs = if e.player.muted != b { e.player.toggle_mute() } else { vec![] };
817:                     drop(e);
818:                     self.eiga_events(evs);
819:                 }
820:                 (2, 2, crate::appkit::SVal::Idx(i)) => e.aspect = i as u8,
821:                 (3, 0, crate::appkit::SVal::F(v)) => e.cfg_hide_secs = v.clamp(1.0, 8.0),
822:                 (3, 1, _) => {
823:                     e.cfg_def_speed = 1.0;
824:                     e.cfg_sub_size = 1.0;
825:                     e.cfg_hide_secs = 2.6;
826:                     e.cfg_double_click = true;
827:                     e.cfg_loop_default = false;
828:                     self.toast("Eiga settings reset", true);
829:                 }
830:                 _ => {}
831:             }
832:         }
833:     }
