217: fn lower_ext(name: &str) -> String {
218:     match name.rsplit_once('.') {
219:         Some((stem, e)) if !stem.is_empty() => e.to_ascii_lowercase(),
220:         _ => String::new(),
221:     }
222: }
223: 
224: fn join(dir: &str, name: &str) -> String {
225:     if dir.ends_with('/') {
226:         format!("{dir}{name}")
227:     } else {
228:         format!("{dir}/{name}")
229:     }
230: }
231: 
232: /// If `name` looks like "base (1).ext" / "base - Copy.ext" / "base copy.ext" returns the original's file name.
233: pub fn copy_original(name: &str) -> Option<String> {
234:     let (stem, ext) = match name.rsplit_once('.') {
235:         Some((s, e)) if !s.is_empty() && e.len() <= 8 => (s, format!(".{e}")),
236:         _ => (name, String::new()),
237:     };
238:     for suf in [" - Copy", " copy", " (copy)", "_copy", "-copy"] {
239:         if let Some(b) = stem.strip_suffix(suf) {
240:             if !b.is_empty() {
241:                 return Some(format!("{b}{ext}"));
242:             }
243:         }
244:     }
245:     // "name (12)"
246:     if let Some(open) = stem.rfind(" (") {
247:         let tail = &stem[open + 2..];
248:         if let Some(num) = tail.strip_suffix(')') {
249:             if !num.is_empty() && num.len() <= 3 && num.bytes().all(|b| b.is_ascii_digit()) && open > 0 {
250:                 return Some(format!("{}{}", &stem[..open], ext));
251:             }
252:         }
253:     }
254:     None
255: }
