257: struct DirClass {
258:     kind: JunkKind,
259:     safety: Safety,
260:     reason: String,
261:     restore: Option<&'static str>,
262: }
263: 
264: fn classify_dir(name: &str, parent_name: &str, siblings: &HashSet<String>) -> Option<DirClass> {
265:     let has = |n: &str| siblings.contains(n);
266:     let has_ext = |e: &str| siblings.iter().any(|s| s.ends_with(e));
267:     let mk = |kind, safety, reason: &str, restore: Option<&'static str>| Some(DirClass { kind, safety, reason: reason.into(), restore });
268:     match name {
269:         "target" if has("Cargo.toml") => mk(JunkKind::BuildArtifacts, Safety::Safe, "Rust build output next to a Cargo.toml", Some("cargo build")),
270:         "target" if has("pom.xml") || has("build.gradle") => mk(JunkKind::BuildArtifacts, Safety::Safe, "Maven/Gradle build output", Some("mvn package")),
271:         "node_modules" => mk(JunkKind::Dependencies, Safety::Safe, "JavaScript packages. The lockfile lists every one", Some("npm install")),
272:         "__pycache__" | ".pytest_cache" | ".mypy_cache" | ".ruff_cache" | ".tox" | ".nox" | ".hypothesis" => mk(JunkKind::Caches, Safety::Safe, "Python tool cache", None),
273:         ".venv" | "venv" => mk(JunkKind::Environments, Safety::Review, "Python virtual environment", Some("python -m venv && pip install -r requirements.txt")),
274:         ".next" | ".nuxt" | ".svelte-kit" | ".turbo" | ".parcel-cache" | ".angular" | ".vite" | ".docusaurus" => mk(JunkKind::BuildArtifacts, Safety::Safe, "Web framework build cache", Some("your dev or build command")),
275:         "dist" if has("package.json") => mk(JunkKind::BuildArtifacts, Safety::Safe, "Bundled output of a JavaScript project", Some("npm run build")),
276:         "build" if has("package.json") || has("CMakeLists.txt") || has("build.gradle") || has("setup.py") || has("pubspec.yaml") => mk(JunkKind::BuildArtifacts, Safety::Safe, "Build folder of a project", Some("your build command")),
277:         ".gradle" | ".dart_tool" | ".stack-work" | ".zig-cache" | "zig-cache" | "DerivedData" => mk(JunkKind::BuildArtifacts, Safety::Safe, "Toolchain build cache", None),
278:         "obj" | "bin" if has_ext(".csproj") || has_ext(".fsproj") => mk(JunkKind::BuildArtifacts, Safety::Safe, ".NET build output", Some("dotnet build")),
279:         "Pods" if has("Podfile") => mk(JunkKind::Dependencies, Safety::Safe, "CocoaPods dependencies", Some("pod install")),
280:         "vendor" if has("composer.json") => mk(JunkKind::Dependencies, Safety::Safe, "Composer packages", Some("composer install")),
281:         "_cacache" => mk(JunkKind::Caches, Safety::Safe, "npm download cache", None),
282:         "registry" | "git" if parent_name == ".cargo" => mk(JunkKind::Caches, Safety::Review, "Cargo crate downloads. Re-fetched on the next build", Some("cargo fetch")),
283:         "repository" if parent_name == ".m2" => mk(JunkKind::Caches, Safety::Review, "Maven local repository", Some("mvn dependency:resolve")),
284:         "caches" if parent_name == ".gradle" => mk(JunkKind::Caches, Safety::Safe, "Gradle download cache", None),
285:         ".cache" | "Cache" | "Caches" | "GPUCache" | "Code Cache" | "CachedData" | "ShaderCache" | "cache2" | "GrShaderCache" | "DawnCache" => mk(JunkKind::Caches, Safety::Safe, "Application cache", None),
286:         "Trash" | ".Trash" => mk(JunkKind::Trash, Safety::Review, "Deleted items waiting to be emptied", None),
287:         n if n.starts_with(".Trash-") => mk(JunkKind::Trash, Safety::Review, "Deleted items waiting to be emptied", None),
288:         "tmp" | "temp" | ".tmp" => mk(JunkKind::Temp, Safety::Review, "Temporary folder", None),
289:         _ => None,
290:     }
291: }
