293: impl Scan {
294:     pub fn new(fs: &str, root: &str, now: i64) -> Scan {
295:         let name = root.rsplit('/').find(|s| !s.is_empty()).unwrap_or("/").to_string();
296:         let node = DirNode { name, path: root.to_string(), parent: None, size: 0, own: 0, files: 0, children: vec![], top_files: vec![], newest: 0, junk: None, in_junk: false, done: false };
297:         Scan { fs: fs.into(), root: root.into(), nodes: vec![node], junk: vec![], buckets: [0; 6], files_seen: 0, dirs_seen: 0, errors: 0, finished: false, now, skip: vec![], queue: vec![0], file_junk: 0 }
298:     }
299: 
300:     /// Skips Linux pseudo file systems so a whole-drive scan never wanders into /proc.
301:     pub fn skip_pseudo(&mut self) {
302:         self.skip = ["/proc", "/sys", "/dev", "/run", "/tmp/.X11-unix"].iter().map(|s| s.to_string()).collect();
303:     }
304: 
305:     pub fn total(&self) -> u64 {
306:         self.nodes.first().map(|n| n.size).unwrap_or(0)
307:     }
308: 
309:     pub fn root_loc(&self) -> Location {
310:         Location::new(self.fs.clone(), self.root.clone())
311:     }
312: 
313:     pub fn loc(&self, path: &str) -> Location {
314:         Location::new(self.fs.clone(), path.to_string())
315:     }
316: 
317:     /// Progress hint 0..1 (directories finished vs discovered; honest about being an estimate).
318:     pub fn progress(&self) -> f32 {
319:         if self.finished {
320:             return 1.0;
321:         }
322:         let done = self.nodes.iter().filter(|n| n.done).count() as f32;
323:         (done / self.nodes.len().max(1) as f32).clamp(0.0, 0.99)
324:     }
325: 
326:     /// Process up to `max_dirs` directories. Returns `true` while there is more to do.
327:     pub fn step(&mut self, vfs: &dyn Vfs, max_dirs: usize) -> bool {
328:         for _ in 0..max_dirs {
329:             let Some(i) = self.queue.pop() else {
330:                 self.finished = true;
331:                 break;
332:             };
333:             self.scan_dir(vfs, i);
334:         }
335:         self.refresh_junk_sizes();
336:         !self.finished
337:     }
338: 
339:     fn add_up(&mut self, mut i: usize, bytes: u64, modified: i64) {
340:         loop {
341:             let n = &mut self.nodes[i];
342:             n.size += bytes;
343:             n.newest = n.newest.max(modified);
344:             match n.parent {
345:                 Some(p) => i = p,
346:                 None => break,
347:             }
348:         }
349:     }
350: 
351:     fn scan_dir(&mut self, vfs: &dyn Vfs, i: usize) {
352:         let path = self.nodes[i].path.clone();
353:         let parent_name = self.nodes[i].parent.map(|p| self.nodes[p].name.clone()).unwrap_or_default();
354:         let _ = parent_name;
355:         let dir_name = self.nodes[i].name.clone();
356:         let in_junk = self.nodes[i].in_junk;
357:         let entries: Vec<Entry> = match vfs.list(&path) {
358:             Ok(v) => v,
359:             Err(_) => {
360:                 self.errors += 1;
361:                 self.nodes[i].done = true;
362:                 return;
363:             }
364:         };
365:         let siblings: HashSet<String> = entries.iter().map(|e| e.name.clone()).collect();
366:         let in_downloads = path.to_ascii_lowercase().contains("download");
367:         for e in entries {
368:             if e.symlink {
369:                 continue;
370:             }
371:             if e.is_dir {
372:                 if self.skip.iter().any(|s| *s == e.loc.path) {
373:                     continue;
374:                 }
375:                 let idx = self.nodes.len();
376:                 let mut node = DirNode { name: e.name.clone(), path: e.loc.path.clone(), parent: Some(i), size: 0, own: 0, files: 0, children: vec![], top_files: vec![], newest: e.modified.unwrap_or(0), junk: None, in_junk, done: false };
377:                 if !in_junk && e.name != ".git" {
378:                     if let Some(c) = classify_dir(&e.name, &dir_name, &siblings) {
379:                         node.junk = Some(self.junk.len());
380:                         node.in_junk = true;
381:                         self.junk.push(Junk { path: e.loc.path.clone(), name: e.name.clone(), is_dir: true, kind: c.kind, safety: c.safety, reason: c.reason, restore: c.restore, modified: e.modified, size: 0, node: Some(idx) });
382:                     }
383:                 }
384:                 self.nodes.push(node);
385:                 self.nodes[i].children.push(idx);
386:                 self.dirs_seen += 1;
387:                 self.queue.push(idx);
388:                 continue;
389:             }
390:             self.files_seen += 1;
391:             let size = e.size;
392:             self.nodes[i].own += size;
393:             self.nodes[i].files += 1;
394:             self.buckets[Bucket::of(e.kind).idx()] += size;
395:             let modified = e.modified.unwrap_or(0);
396:             self.add_up(i, size, modified);
397:             // keep the biggest files
398:             if self.nodes[i].top_files.len() < TOP_FILES || self.nodes[i].top_files.last().map(|f| f.size < size).unwrap_or(true) {
399:                 let fi = FileInfo { name: e.name.clone(), path: e.loc.path.clone(), size, modified: e.modified, kind: e.kind };
400:                 let tf = &mut self.nodes[i].top_files;
401:                 let pos = tf.iter().position(|f| f.size < size).unwrap_or(tf.len());
402:                 tf.insert(pos, fi);
403:                 tf.truncate(TOP_FILES);
404:             }
405:             if !in_junk && self.file_junk < MAX_FILE_JUNK {
406:                 if let Some(j) = self.classify_file(&e, &siblings, in_downloads) {
407:                     self.file_junk += 1;
408:                     self.junk.push(j);
409:                 }
410:             }
411:         }
412:         self.nodes[i].done = true;
413:     }
414: 
415:     fn classify_file(&self, e: &Entry, siblings: &HashSet<String>, in_downloads: bool) -> Option<Junk> {
416:         let name = e.name.as_str();
417:         let ext = lower_ext(name);
418:         let size = e.size;
419:         let age_days = e.modified.map(|m| ((self.now - m) / DAY).max(0));
420:         let mk = |kind, safety, reason: String, restore| Some(Junk { path: e.loc.path.clone(), name: e.name.clone(), is_dir: false, kind, safety, reason, restore, modified: e.modified, size, node: None });
421:         // temporary leftovers
422:         let temp_ext = matches!(ext.as_str(), "tmp" | "temp" | "bak" | "swp" | "swo" | "crdownload" | "part" | "partial" | "orig" | "dmp");
423:         let temp_name = name.ends_with('~') || matches!(name, ".DS_Store" | "Thumbs.db" | "desktop.ini") || (name.starts_with("core.") && name[5..].bytes().all(|b| b.is_ascii_digit()) && name.len() > 5);
424:         if (temp_ext || temp_name) && size >= 64 * 1024 {
425:             return mk(JunkKind::Temp, Safety::Safe, if ext == "crdownload" || ext == "part" || ext == "partial" { "Unfinished download".into() } else { "Temporary or backup leftover".into() }, None);
426:         }
427:         if (ext == "log" || name.contains(".log.")) && size >= 5 * 1024 * 1024 {
428:             return mk(JunkKind::Logs, Safety::Safe, format!("Log file of {}", crate::model::format_size(size)), None);
429:         }
430:         if in_downloads && matches!(ext.as_str(), "iso" | "dmg" | "pkg" | "exe" | "msi" | "deb" | "rpm" | "apk") && size >= 1024 * 1024 && age_days.map(|d| d >= 14).unwrap_or(false) {
431:             return mk(JunkKind::Installers, Safety::Review, format!("Installer in Downloads, untouched for {} days", age_days.unwrap_or(0)), None);
432:         }
433:         if size >= 100 * 1024 {
434:             if let Some(orig) = copy_original(name) {
435:                 if siblings.contains(&orig) {
436:                     return mk(JunkKind::Duplicates, Safety::Review, format!("Looks like a copy of \u{201c}{orig}\u{201d} in the same folder"), None);
437:                 }
438:             }
439:         }
440:         if let Some(d) = age_days {
441:             let archive = e.kind == Kind::Archive;
442:             if (size >= 200 * 1_000_000 && d >= 365) || (size >= 1_000_000_000 && d >= 120) || (archive && size >= 100 * 1_000_000 && d >= 180) {
443:                 let months = (d / 30).max(1);
444:                 return mk(JunkKind::LargeStale, Safety::Careful, format!("{} untouched for {} month{}", if archive { "Old archive" } else { "Large file" }, months, if months == 1 { "" } else { "s" }), None);
445:             }
446:         }
447:         None
448:     }
449: 
450:     fn refresh_junk_sizes(&mut self) {
451:         for j in &mut self.junk {
452:             if let Some(n) = j.node {
453:                 j.size = self.nodes[n].size;
454:             }
455:         }
456:     }
457: 
458:     /// Candidates worth showing, best first: weight favours big *and* safe.
459:     pub fn candidates(&self) -> Vec<&Junk> {
460:         let mut v: Vec<&Junk> = self.junk.iter().filter(|j| j.size >= MIN_JUNK_BYTES).collect();
461:         v.sort_by_key(|j| {
462:             let w = match j.safety {
463:                 Safety::Safe => 3,
464:                 Safety::Review => 2,
465:                 Safety::Careful => 1,
466:             };
467:             std::cmp::Reverse(j.size / 4 * w)
468:         });
469:         v
470:     }
471: 
472:     pub fn reclaimable(&self, safe_only: bool) -> u64 {
473:         self.candidates().iter().filter(|j| !safe_only || j.safety == Safety::Safe).map(|j| j.size).sum()
474:     }
475: 
476:     pub fn by_kind(&self) -> Vec<(JunkKind, u64, usize)> {
477:         let mut out = vec![];
478:         for k in JunkKind::ALL {
479:             let (s, n) = self.candidates().iter().filter(|j| j.kind == k).fold((0u64, 0usize), |(s, n), j| (s + j.size, n + 1));
480:             if n > 0 {
481:                 out.push((k, s, n));
482:             }
483:         }
484:         out.sort_by_key(|x| std::cmp::Reverse(x.1));
485:         out
486:     }
487: 
488:     /// The biggest individual files anywhere in the scanned tree.
489:     pub fn biggest_files(&self, n: usize) -> Vec<&FileInfo> {
490:         let mut v: Vec<&FileInfo> = self.nodes.iter().flat_map(|d| d.top_files.iter()).collect();
491:         v.sort_by_key(|f| std::cmp::Reverse(f.size));
492:         v.truncate(n);
493:         v
494:     }
495: 
496:     /// Biggest folders (excluding the root), skipping folders that merely wrap one huge child.
497:     pub fn biggest_dirs(&self, n: usize) -> Vec<usize> {
498:         let mut v: Vec<usize> = (1..self.nodes.len()).collect();
499:         v.sort_by_key(|i| std::cmp::Reverse(self.nodes[*i].size));
500:         v.truncate(n);
501:         v
502:     }
503: 
504:     /// Ancestors of a node from the root to the node, as indices.
505:     pub fn chain(&self, mut i: usize) -> Vec<usize> {
506:         let mut v = vec![i];
507:         while let Some(p) = self.nodes[i].parent {
508:             v.push(p);
509:             i = p;
510:         }
511:         v.reverse();
512:         v
513:     }
514: 
515:     pub fn find(&self, path: &str) -> Option<usize> {
516:         self.nodes.iter().position(|n| n.path == path)
517:     }
518: 
519:     /// Children of a folder as drawable items (folders first by size, then big files, then one "other files" slice).
520:     pub fn items(&self, i: usize) -> Vec<Item> {
521:         let n = &self.nodes[i];
522:         let mut v: Vec<Item> = n.children.iter().map(|c| Item { label: self.nodes[*c].name.clone(), size: self.nodes[*c].size, node: Some(*c), path: self.nodes[*c].path.clone(), is_dir: true, junk: self.nodes[*c].junk.is_some(), kind: Kind::Folder, modified: Some(self.nodes[*c].newest) }).collect();
523:         let shown: u64 = n.top_files.iter().map(|f| f.size).sum();
524:         for f in &n.top_files {
525:             v.push(Item { label: f.name.clone(), size: f.size, node: None, path: f.path.clone(), is_dir: false, junk: false, kind: f.kind, modified: f.modified });
526:         }
527:         if n.own > shown {
528:             v.push(Item { label: format!("{} other files", n.files.saturating_sub(n.top_files.len() as u64)), size: n.own - shown, node: None, path: String::new(), is_dir: false, junk: false, kind: Kind::Other, modified: None });
529:         }
530:         v.retain(|x| x.size > 0);
531:         v.sort_by_key(|x| std::cmp::Reverse(x.size));
532:         v
533:     }
534: }
