536: #[derive(Clone, Debug)]
537: pub struct Item {
538:     pub label: String,
539:     pub size: u64,
540:     pub node: Option<usize>,
541:     pub path: String,
542:     pub is_dir: bool,
543:     pub junk: bool,
544:     pub kind: Kind,
545:     pub modified: Option<i64>,
546: }
