//! ffmpeg-CLI decode bridge (`ffmpeg-cli` feature).
//!
//! Spawns the system `ffmpeg` binary as a decoding subprocess — decodes
//! EVERYTHING installed codecs handle (HEVC Main10, AV1, VP9, Hi10P,
//! Opus…) with zero unsafe bindings and zero build deps. This is the tier
//! that makes real-world libraries playable; pure-Rust tiers remain for
//! targets without the binary.
//!
//! Design: two pipes per playback
//! - video: `-f rawvideo -pix_fmt rgba` → FrameLatch publisher thread
//! - audio: `-f f32le -ar 48000 -ac N` → [`MediaEngine::play_pcm_stream`]

use crate::error::{MediaError, MediaResult};
use crate::latch::{FrameLatch, PixelFormat};
use alloc::string::String;
use alloc::sync::Arc;
use alloc::vec::Vec;
use core::sync::atomic::{AtomicBool, AtomicI64, Ordering};

/// Container/track metadata from ffprobe.
#[derive(Debug, Clone)]
pub struct FfProbeInfo {
    pub duration_ns: i64,
    /// Video stream dims (0 when no video).
    pub width: u32,
    pub height: u32,
    pub fps_num: u32,
    pub fps_den: u32,
    /// Audio track indices (ffmpeg `0:a:N` positions).
    pub audio_tracks: usize,
    pub audio_langs: Vec<String>,
    /// Subtitle tracks with language tags.
    pub sub_langs: Vec<String>,
}

/// Run ffprobe and parse the essentials (no serde — flat CSV output).
pub fn probe(path: impl AsRef<std::path::Path>) -> MediaResult<FfProbeInfo> {
    let out = std::process::Command::new("ffprobe")
        .args([
            "-v", "error",
            "-show_entries",
            "format=duration:stream=index,codec_type,width,height,r_frame_rate,duration:stream_tags=language",
            "-of", "csv=p=0",
        ])
        .arg(path.as_ref())
        .output()
        .map_err(|_| MediaError::UnsupportedFormat)?;

    if !out.status.success() {
        return Err(MediaError::UnsupportedFormat);
    }
    let text = String::from_utf8_lossy(&out.stdout);

    let mut info = FfProbeInfo {
        duration_ns: 0,
        width: 0,
        height: 0,
        fps_num: 24,
        fps_den: 1,
        audio_tracks: 0,
        audio_langs: Vec::new(),
        sub_langs: Vec::new(),
    };

    for line in text.lines() {
        let f: Vec<&str> = line.split(',').collect();
        match f.first().copied().unwrap_or("") {
            // format line: "<duration>,"
            d if f.len() == 1 && d.parse::<f64>().is_ok() => {
                info.duration_ns = (d.parse::<f64>().unwrap_or(0.0) * 1e9) as i64;
            }
            // stream lines: "<idx>,<type>,..." — type in field 1
            _ => {
                if f.len() >= 3 {
                    match f[1] {
                        "video" => {
                            if info.width == 0 {
                                info.width = f.get(2).and_then(|v| v.parse().ok()).unwrap_or(0);
                                info.height = f.get(3).and_then(|v| v.parse().ok()).unwrap_or(0);
                                if let Some(rate) = f.get(5).or_else(|| f.get(4)) {
                                    let mut parts = rate.splitn(2, '/');
                                    info.fps_num = parts.next().and_then(|v| v.parse().ok()).unwrap_or(24);
                                    info.fps_den = parts.next().and_then(|v| v.parse().ok()).unwrap_or(1);
                                }
                            }
                        }
                        "audio" => {
                            info.audio_tracks += 1;
                            // Language tag is the trailing CSV field when present.
                            let lang = f.last().copied().unwrap_or("");
                            let label = if is_lang_tag(lang) {
                                alloc::format!("{}", lang)
                            } else {
                                alloc::format!("{}", info.audio_tracks)
                            };
                            info.audio_langs.push(label);
                        }
                        "subtitle" => {
                            let lang = f.last().copied().unwrap_or("");
                            let label = if is_lang_tag(lang) {
                                alloc::format!("{}", lang)
                            } else {
                                alloc::format!(
                                    "sub {}",
                                    info.sub_langs.len() + 1
                                )
                            };
                            info.sub_langs.push(label);
                        }
                        _ => {}
                    }
                }
            }
        }
    }
    if info.width == 0 && info.audio_tracks == 0 {
        return Err(MediaError::UnsupportedFormat);
    }
    Ok(info)
}

/// A language tag: short alphabetic token, not a number/rate/N-A.
fn is_lang_tag(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 8
        && s.chars().all(|c| c.is_ascii_alphabetic())
}

fn even(v: u32) -> u32 {
    v & !1
}

