        self.sub_idx.and_then(|i| self.sub_tracks.get(i)).and_then(
            |(_, t)| t.cue_at(MediaTime::from_ms(self.position_ms)).map(|c| c.text()),
        )
    }

    fn fmt_pos(&self) -> String {
        let f = |ms: i64| {
            let t = ms.max(0) / 1000;
            format!("{:02}:{:02}:{:02}", t / 3600, (t % 3600) / 60, t % 60)
        };
        format!("{} / {}", f(self.position_ms), f(self.duration_ms))
    }

